params.script:
var files := {
"res://scripts/battle/turn_manager.gd": "",
"res://tests/smoke_test.gd": ""
}
var written := []
for p in files:
	var f := FileAccess.open(p, FileAccess.WRITE)
	if f == null:
		push_error("BRIDGE-WRITE-FAIL: " + p)
		continue
	f.store_string(Marshalls.base64_to_utf8(files[p]))
	f.close()
	written.append(p)
EditorInterface.get_resource_filesystem().scan()
print("BRIDGE-WRITE-OK: " + str(written.size()) + " files written, rescan queued")
